import json, sqlite3
conn=sqlite3.connect('db/users.db')
users={r['Id']:{'UpVotes':r['UpVotes'],'Age':r['Age']}for r in conn.execute('SELECT Id,UpVotes,Age FROM users').fetchall()}
conn.close()
with open('json/posts.json') as f: data=json.load(f)
posts=data['records']
user_post_count={}
for p in posts:
    uid=p.get('OwnerUserId')
    if uid:
        user_post_count[uid]=user_post_count.get(uid,0)+1
total_upvotes=0
total_age=0
count=0
for uid in user_post_count:
    if user_post_count[uid]>10 and uid in users:
        u=users[uid]
        if u['UpVotes'] and u['Age']:
            total_upvotes+=u['UpVotes']
            total_age+=u['Age']
            count+=1
if count>0:
    print(f"AVG_UPVOTES:{total_upvotes/count:.2f}")
    print(f"AVG_AGE:{total_age/count:.2f}")
else:
    print("No users found with >10 posts")

